css:
:root{
  --navy:#0d2545; --navy-2:#123056; --navy-3:#0a1c37;
  --blue:#2898b8; --blue-d:#207f97; --blue-050:#e7f3f6;
  --gold:#f06a1a; --gold-2:#f8863a; --gold-d:#c05313;
  --ink:#14243d; --body:#48566b; --muted:#8592a6;
  --mist:#eef3f8; --mist-2:#f6f9fc; --line:#dbe3ee; --line-ink:rgba(255,255,255,.14);
  --white:#fff;
  --max:1300px; --gut:40px;
  --disp:"Oswald",Impact,"Arial Narrow",sans-serif;
  --f:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--f);color:var(--body);background:var(--white);line-height:1.7;-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{text-decoration:none;color:inherit}
img{max-width:100%;display:block}
h1,h2,h3,h4{margin:0;color:var(--ink);font-family:var(--disp);font-weight:600;line-height:1.04;text-transform:uppercase;letter-spacing:.005em}
p{margin:0}
.wrap{max-width:var(--max);margin:0 auto;padding:0 var(--gut)}
.ic{width:1em;height:1em;flex:none;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:square;stroke-linejoin:miter}
.olabel{display:inline-flex;align-items:center;gap:14px;font-family:var(--f);font-size:.72rem;font-weight:700;letter-spacing:.28em;text-transform:uppercase;color:var(--ink)}
.olabel .num{color:var(--gold-d);font-variant-numeric:tabular-nums;font-family:var(--disp);font-size:1rem}
.olabel .bar{width:40px;height:2px;background:var(--gold)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:12px;font-family:var(--f);font-weight:700;font-size:.78rem;letter-spacing:.16em;text-transform:uppercase;padding:17px 32px;border:2px solid var(--navy);color:var(--navy);background:transparent;cursor:pointer;transition:.22s;position:relative;overflow:hidden;isolation:isolate}
.btn>*{position:relative;z-index:1}
.btn::before{content:"";position:absolute;inset:0;background:var(--navy);transform:translateY(101%);transition:.28s;z-index:-1}
.btn:hover::before{transform:translateY(0)}
.btn:hover{color:#fff;border-color:var(--navy)}
.btn-gold{border-color:var(--gold);color:var(--navy);background:var(--gold)}
.btn-gold::before{background:var(--gold-d)}
.btn-gold:hover{color:#fff;border-color:var(--gold-d)}
.btn-blue{border-color:var(--blue);color:#fff;background:var(--blue)}
.btn-blue::before{background:var(--blue-d)}
.btn-blue:hover{color:#fff;border-color:var(--blue-d)}
.btn-light{border-color:rgba(255,255,255,.7);color:#fff}
.btn-light::before{background:#fff}
.btn-light:hover{color:var(--navy);border-color:#fff}
.btn .ic{width:15px;height:15px;stroke-width:2.4}
.section{padding:112px 0;position:relative}
.section.tight{padding:84px 0}
/* Nifty-safe reveal: content is ALWAYS visible even if scripts are stripped on import */
.rv{animation:rvIn .8s cubic-bezier(.2,.7,.2,1) both}
.rv.d1{animation-delay:.10s}.rv.d2{animation-delay:.20s}.rv.d3{animation-delay:.30s}
@keyframes rvIn{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.rv{animation:none}}
.wm{position:absolute;font-family:var(--disp);font-weight:700;font-size:22rem;line-height:.7;color:var(--navy);opacity:.045;pointer-events:none;z-index:0;letter-spacing:-.04em}
.lead-lg{font-size:1.12rem;color:var(--body);max-width:60ch}

/* placeholder image */
.ph{background:var(--mist);display:block;width:100%;height:100%;object-fit:cover}

/* ============ TOP BAR ============ */
.topbar{background:var(--navy);color:#c3d0e2;font-size:.74rem;letter-spacing:.08em;position:relative;z-index:40}
.topbar .wrap{display:flex;align-items:center;justify-content:space-between;min-height:42px;gap:16px}
.topbar .tb-l{display:flex;gap:26px;text-transform:uppercase}
.topbar .tb-l span{display:inline-flex;align-items:center;gap:9px}
.topbar .ic{width:14px;height:14px;color:var(--gold);stroke-width:2.4}
.topbar a{color:#fff;font-weight:700}
.topbar a:hover{color:var(--gold)}
@media(max-width:820px){.topbar .tb-l span.hide-sm{display:none}}

/* ============ HEADER ============ */
.hdr{position:absolute;top:0;left:0;right:0;z-index:60}
.hdr.solid{position:fixed;top:0;background:rgba(13,37,69,.96);backdrop-filter:blur(10px);border-bottom:3px solid var(--gold);animation:drop .35s ease}
@keyframes drop{from{transform:translateY(-100%)}to{transform:none}}
.hdr-in{display:flex;align-items:center;gap:30px;min-height:92px}
.brand{flex:none;display:flex;align-items:center}
.brand img{height:64px;width:auto;display:block}
.nav-cb{display:none}
.nav{margin-left:auto;display:flex;align-items:center;gap:34px}
.nav-links{display:flex;align-items:center;gap:28px;list-style:none;margin:0;padding:0}
.nav-links>li{position:relative}
.nav-links>li>a{display:flex;align-items:center;gap:7px;font-family:var(--f);font-size:.8rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#fff;position:relative;padding:8px 0}
.nav-links>li>a .caret{width:13px;height:13px;stroke-width:2.4}
.nav-links>li>a::after{content:"";position:absolute;left:0;bottom:0;width:0;height:2px;background:var(--gold);transition:.28s}
.nav-links>li>a:hover::after,.nav-links>li.active>a::after{width:100%}
.nav-links>li.active>a{color:var(--gold)}
/* dropdown */
.has-drop .drop-cb{display:none}
.dropdown{position:absolute;top:calc(100% + 10px);left:50%;transform:translateX(-50%);min-width:250px;background:#fff;border:1px solid var(--line);box-shadow:0 24px 50px rgba(13,37,69,.18);padding:8px;opacity:0;visibility:hidden;transition:.16s;z-index:70}
.has-drop:hover .dropdown{opacity:1;visibility:visible;top:calc(100% + 2px)}
.dropdown a{display:flex;align-items:center;gap:11px;padding:12px 14px;font-family:var(--f);font-size:.82rem;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--ink)}
.dropdown a:hover{background:var(--mist);color:var(--blue-d)}
.dropdown a .dot{width:7px;height:7px;background:var(--gold);flex:none;transform:rotate(45deg)}
.hdr-cta{display:flex;align-items:center;gap:22px;flex:none}
.hdr-cta .call{display:inline-flex;align-items:center;gap:12px;color:#fff;transition:.2s}
.hdr-cta .call .ci{width:44px;height:44px;border:2px solid rgba(255,255,255,.32);border-radius:50%;display:grid;place-items:center;color:var(--gold);flex:none;transition:.2s}
.hdr-cta .call .ci .ic{width:19px;height:19px;stroke-width:2.2}
.hdr-cta .call .ct{display:flex;flex-direction:column;line-height:1.15}
.hdr-cta .call .ct small{font-family:var(--f);font-size:.62rem;letter-spacing:.16em;text-transform:uppercase;color:#9fb0c6;font-weight:700}
.hdr-cta .call .ct b{font-family:var(--disp);font-size:1.3rem;color:#fff;font-weight:600;letter-spacing:.01em}
.hdr-cta .call:hover .ci{background:var(--gold);border-color:var(--gold);color:var(--navy)}
.hdr-cta .call:hover .ct b{color:var(--gold)}
.hdr-cta .quote{background:var(--gold);color:var(--navy);padding:16px 26px;font-family:var(--f);font-size:.8rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;transition:.2s;clip-path:polygon(10px 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%,0 10px)}
.hdr-cta .quote:hover{background:#fff}
.burger{display:none;margin-left:auto;width:50px;height:50px;border:2px solid rgba(255,255,255,.5);align-items:center;justify-content:center;color:#fff;cursor:pointer;background:transparent}
.burger svg{width:22px;height:22px;stroke-width:2.4}
.burger .x{display:none}
.nav-cb:checked ~ .burger .menu{display:none}.nav-cb:checked ~ .burger .x{display:block}
@media(max-width:1140px){
  .burger{display:flex}
  .nav{position:fixed;inset:0 0 0 auto;top:0;height:100vh;width:min(380px,88vw);margin:0;background:var(--navy);flex-direction:column;align-items:stretch;gap:0;padding:92px 0 30px;transform:translateX(105%);transition:transform .32s ease;overflow-y:auto;z-index:80;border-left:3px solid var(--gold)}
  .nav-cb:checked ~ .nav{transform:translateX(0)}
  .nav-links{flex-direction:column;align-items:stretch;gap:0;width:100%}
  .nav-links>li{width:100%}
  .nav-links>li>a{justify-content:space-between;padding:19px 32px;border-bottom:1px solid var(--line-ink);letter-spacing:.14em;font-size:.98rem;font-family:var(--disp);font-weight:500}
  .nav-links>li>a::after{display:none}
  .nav-links>li>a:hover{background:var(--navy-2);color:var(--gold)}
  .nav-links>li.has-drop>a{display:none}
  .dropdown{position:static;transform:none!important;left:auto;opacity:1;visibility:visible;box-shadow:none;border:0;min-width:0;padding:0;max-height:0;overflow:hidden;transition:max-height .3s ease;background:var(--navy-2)}
  .has-drop:hover .dropdown{transform:none!important;left:auto;top:auto}
  .drop-cb:checked ~ .dropdown{max-height:400px}
  .drop-lbl{display:flex!important;align-items:center;justify-content:space-between;padding:19px 32px;border-bottom:1px solid var(--line-ink);color:#fff;font-family:var(--disp);font-weight:500;font-size:.98rem;letter-spacing:.14em;text-transform:uppercase;cursor:pointer}
  .drop-cb:checked ~ .drop-lbl .caret{transform:rotate(180deg)}
  .drop-lbl .caret{width:15px;height:15px;stroke-width:2.4;transition:.25s}
  .dropdown a{color:#cdd8e6;padding:15px 40px}
  .dropdown a:hover{background:var(--navy-3);color:var(--gold)}
  .hdr-cta{display:none}
  .nav .m-cta{display:flex;flex-direction:column;margin-top:auto}
  .nav .m-cta a{padding:20px 32px;text-align:center;font-size:.85rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;font-family:var(--f)}
  .nav .m-cta .mc-call{border-top:1px solid var(--line-ink);border-bottom:1px solid var(--line-ink)}
  .nav .m-cta .mc-quote{background:var(--gold);color:var(--navy)}
}
@media(min-width:1141px){.nav .m-cta{display:none}.drop-lbl{display:none}}
.scrim{display:none}
@media(max-width:1140px){.nav-cb:checked ~ .scrim{display:block;position:fixed;inset:0;background:rgba(10,20,40,.55);z-index:75}}

/* ============ HERO (home) ============ */
.hero{position:relative;min-height:100vh;display:flex;align-items:center;overflow:hidden;
  background:radial-gradient(900px 520px at 86% 6%,rgba(40,152,184,.30),transparent 60%),radial-gradient(720px 520px at 2% 104%,rgba(240,106,26,.16),transparent 55%),linear-gradient(158deg,#143561 0%,#0d2545 54%,#081a33 100%)}
.hero-bg{position:absolute;inset:0}
.hero-bg img{width:100%;height:100%;object-fit:cover;opacity:.5;transform:scale(1.08);animation:kb 18s ease-out forwards}
@keyframes kb{to{transform:scale(1)}}
.hero-bg::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(10,24,45,.94) 0%,rgba(10,24,45,.66) 42%,rgba(10,24,45,.34) 100%),linear-gradient(180deg,transparent 52%,rgba(10,24,45,.9) 100%)}
.hero-grain{position:absolute;inset:0;opacity:.5;pointer-events:none;background-image:linear-gradient(rgba(255,255,255,.03) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.03) 1px,transparent 1px);background-size:52px 52px;z-index:2}
.hero-inner{position:relative;z-index:4;width:100%;padding:150px 0 0}
.hero-kicker{display:inline-flex;align-items:center;gap:14px;color:#fff;font-size:.76rem;font-weight:700;letter-spacing:.26em;text-transform:uppercase;margin-bottom:26px}
.hero-kicker::before{content:"";width:46px;height:2px;background:var(--gold)}
.hero h1{color:#fff;font-family:var(--disp);font-weight:700;font-size:clamp(3.2rem,10vw,9rem);line-height:.92;letter-spacing:-.01em;text-transform:uppercase}
.hero h1 .out{-webkit-text-stroke:2px rgba(255,255,255,.55);color:transparent;display:inline-block}
.hero h1 .amp{color:var(--gold)}
.hero-tag{margin-top:30px;color:#d3ddec;font-size:1.1rem;max-width:46ch;font-family:var(--f);border-left:3px solid var(--gold);padding-left:20px}
.hero-cta{display:flex;flex-wrap:wrap;gap:16px;margin-top:38px}
.hero-stats{position:relative;z-index:4;margin-top:66px;border-top:1px solid rgba(255,255,255,.16)}
.hero-stats .wrap{display:grid;grid-template-columns:repeat(4,1fr)}
.hstat{padding:26px 30px 34px;border-right:1px solid rgba(255,255,255,.12)}
.hstat:last-child{border-right:0}
.hstat b{font-family:var(--disp);font-weight:700;font-size:2.7rem;color:#fff;line-height:1;display:block}
.hstat b span{color:var(--gold)}
.hstat small{color:#9fb0c6;font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;font-weight:600;margin-top:8px;display:block}
.hero-scroll{position:absolute;right:var(--gut);bottom:150px;z-index:4;writing-mode:vertical-rl;color:rgba(255,255,255,.6);font-size:.68rem;letter-spacing:.3em;text-transform:uppercase;display:flex;align-items:center;gap:14px}
.hero-scroll::after{content:"";width:1px;height:60px;background:linear-gradient(var(--gold),transparent)}
@media(max-width:900px){.hero-inner{padding-top:130px}.hero-stats .wrap{grid-template-columns:1fr 1fr}.hstat{border-bottom:1px solid rgba(255,255,255,.12)}.hstat:nth-child(2){border-right:0}.hero-scroll{display:none}}
@media(max-width:520px){.hstat b{font-size:2rem}}

/* ============ SUBHERO (interior pages) ============ */
.subhero{position:relative;overflow:hidden;padding:170px 0 70px;
  background:radial-gradient(680px 380px at 90% 0%,rgba(40,152,184,.24),transparent 62%),radial-gradient(560px 360px at 0% 100%,rgba(240,106,26,.12),transparent 55%),linear-gradient(160deg,#143561 0%,#0d2545 60%,#081a33 100%)}
.subhero-bg{position:absolute;inset:0}
.subhero-bg img{width:100%;height:100%;object-fit:cover;opacity:.32}
.subhero-bg::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(10,24,45,.86),rgba(10,24,45,.94))}
.subhero .grain{position:absolute;inset:0;opacity:.5;pointer-events:none;background-image:linear-gradient(rgba(255,255,255,.03) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.03) 1px,transparent 1px);background-size:52px 52px;z-index:1}
.subhero .wrap{position:relative;z-index:2}
.crumb{display:flex;align-items:center;gap:10px;color:#9fb0c6;font-family:var(--f);font-size:.74rem;letter-spacing:.14em;text-transform:uppercase;font-weight:600;margin-bottom:20px}
.crumb a{color:#9fb0c6}.crumb a:hover{color:var(--gold)}
.crumb .sep{color:var(--gold)}
.crumb span[aria-current]{color:#fff}
.subhero h1{color:#fff;font-size:clamp(2.4rem,6vw,4.6rem);line-height:.98}
.subhero h1 em{font-style:normal;color:var(--gold)}
.subhero p{color:#d3ddec;font-family:var(--f);font-size:1.1rem;max-width:52ch;margin-top:20px;border-left:3px solid var(--gold);padding-left:20px}

/* ============ MARQUEE ============ */
.marquee{background:var(--navy);color:#fff;overflow:hidden;padding:20px 0;position:relative;z-index:5;border-top:3px solid var(--gold)}
.marquee-track{display:flex;width:max-content;animation:scroll 26s linear infinite}
.marquee:hover .marquee-track{animation-play-state:paused}
.marquee span{font-family:var(--disp);font-weight:600;font-size:1.5rem;text-transform:uppercase;letter-spacing:.04em;padding:0 34px;display:inline-flex;align-items:center;gap:34px;white-space:nowrap}
.marquee span::after{content:"\25C6";font-size:.7rem;color:var(--gold)}
@keyframes scroll{to{transform:translateX(-50%)}}

/* ============ OVERVIEW / SPLIT ============ */
.split{background:var(--white);overflow:hidden}
.split.alt{background:var(--mist)}
.ov-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:80px;align-items:center;position:relative;z-index:1}
.ov-grid.rev .ov-fig{order:2}
.ov-copy h2{font-size:clamp(2rem,3.6vw,2.9rem);margin:24px 0 24px;line-height:1.05}
.ov-copy h2 em{font-style:normal;color:var(--blue)}
.ov-copy p{margin-bottom:18px;font-size:1.03rem}
.ov-copy .btn{margin-top:20px}
.ov-fig{position:relative}
.ov-fig .imgwrap{overflow:hidden;position:relative;aspect-ratio:4/5}
.ov-fig img{width:100%;height:100%;object-fit:cover;transition:.6s}
.ov-fig:hover img{transform:scale(1.05)}
.ov-fig .tab{position:absolute;left:-1px;bottom:-1px;background:var(--gold);color:var(--navy);padding:22px 28px;max-width:230px;clip-path:polygon(0 0,100% 0,100% 100%,20px 100%,0 calc(100% - 20px))}
.ov-fig .tab b{font-family:var(--disp);display:block;font-size:2.5rem;font-weight:700;line-height:1}
.ov-fig .tab small{font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;opacity:.92;margin-top:6px;display:block;font-weight:700}
.ov-fig::before{content:"";position:absolute;top:-20px;right:-20px;width:130px;height:130px;border:3px solid var(--blue);z-index:-1}
.ov-grid.rev .ov-fig::before{left:-20px;right:auto}
@media(max-width:900px){.ov-grid{grid-template-columns:1fr;gap:46px}.ov-fig,.ov-grid.rev .ov-fig{order:-1}}

/* section heading center */
.sec-head{max-width:720px;margin:0 auto 52px;text-align:center;position:relative;z-index:1}
.sec-head .olabel{justify-content:center}
.sec-head h2{font-size:clamp(2rem,4vw,3rem);margin-top:18px}
.sec-head h2 em{font-style:normal;color:var(--blue)}
.sec-head p{margin-top:16px;font-size:1.06rem;color:var(--body)}
.dark .sec-head h2{color:#fff}.dark .sec-head p{color:#c1cede}.dark .olabel{color:#fff}

/* ============ SERVICES tiles ============ */
.services{background:var(--navy);color:#fff;overflow:hidden}
.services .olabel{color:#fff}
.svc-head{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:end;margin-bottom:52px;position:relative;z-index:1}
.svc-head h2{color:#fff;font-size:clamp(2rem,4vw,3.2rem);margin-top:20px}
.svc-head p{font-size:1.06rem;color:#c1cede;font-family:var(--f)}
.svc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.12)}
.svc{position:relative;min-height:430px;overflow:hidden;background:var(--navy-2);display:flex;flex-direction:column;justify-content:flex-end}
.svc img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:brightness(.55);transition:.55s}
.svc:hover img{filter:brightness(.72);transform:scale(1.08)}
.svc::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(13,37,69,.1) 30%,rgba(10,24,45,.92) 100%)}
.svc .bignum{position:absolute;top:22px;left:24px;z-index:2;font-family:var(--disp);font-weight:700;font-size:3.2rem;color:rgba(255,255,255,.24);line-height:1;transition:.35s}
.svc:hover .bignum{color:var(--gold)}
.svc .svc-body{position:relative;z-index:2;padding:28px 26px}
.svc h3{color:#fff;font-size:1.35rem;font-weight:600;line-height:1.06}
.svc .go{display:flex;align-items:center;gap:10px;margin-top:13px;color:#fff;font-family:var(--f);font-size:.72rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;max-height:0;opacity:0;overflow:hidden;transition:.4s}
.svc:hover .go{max-height:40px;opacity:1}
.svc .go .ic{width:15px;height:15px;stroke-width:2.6;color:var(--gold)}
.svc .rbar{position:absolute;left:0;bottom:0;height:5px;width:0;background:var(--gold);z-index:3;transition:.4s}
.svc:hover .rbar{width:100%}
.svc-foot{display:flex;align-items:center;justify-content:space-between;gap:22px;margin-top:46px;flex-wrap:wrap;border-top:1px solid rgba(255,255,255,.14);padding-top:32px}
.svc-foot span{font-family:var(--disp);font-size:1.5rem;color:#fff;text-transform:uppercase;font-weight:500}
@media(max-width:960px){.svc-grid{grid-template-columns:1fr 1fr}.svc-head{grid-template-columns:1fr;gap:18px}}
@media(max-width:520px){.svc-grid{grid-template-columns:1fr}.svc{min-height:320px}}

/* ============ SERVICE LIST cards (services page) ============ */
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;position:relative;z-index:1}
.cards.two{grid-template-columns:repeat(2,1fr)}
.card{background:#fff;border:1px solid var(--line);padding:0;transition:.28s;display:flex;flex-direction:column;overflow:hidden}
.card:hover{transform:translateY(-8px);box-shadow:0 30px 60px rgba(13,37,69,.14);border-color:transparent}
.card .cimg{aspect-ratio:16/10;overflow:hidden;position:relative}
.card .cimg img{width:100%;height:100%;object-fit:cover;transition:.5s}
.card:hover .cimg img{transform:scale(1.06)}
.card .cnum{position:absolute;top:0;left:0;background:var(--navy);color:#fff;font-family:var(--disp);font-weight:700;font-size:1rem;padding:8px 16px;letter-spacing:.1em}
.card .cbody{padding:28px 28px 30px;display:flex;flex-direction:column;flex:1}
.card h3{font-size:1.3rem;font-weight:600}
.card p{margin-top:11px;font-size:.96rem;color:var(--body);flex:1}
.card .clink{display:inline-flex;align-items:center;gap:10px;margin-top:20px;font-family:var(--f);font-size:.72rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--navy);border-bottom:2px solid var(--gold);padding-bottom:5px;align-self:flex-start}
.card .clink .ic{width:15px;height:15px;stroke-width:2.6;transition:.2s}
.card .clink:hover .ic{transform:translateX(5px)}
@media(max-width:960px){.cards,.cards.two{grid-template-columns:1fr 1fr}}
@media(max-width:620px){.cards,.cards.two{grid-template-columns:1fr}}

/* ============ VALUES / FEATURE grid ============ */
.feat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);position:relative;z-index:1}
.feat{background:#fff;padding:34px 30px;transition:.25s}
.feat:hover{background:var(--mist-2)}
.feat .fi{width:52px;height:52px;background:var(--blue-050);color:var(--blue-d);display:grid;place-items:center;margin-bottom:18px}
.feat .fi .ic{width:26px;height:26px;stroke-width:1.8}
.feat h3{font-size:1.16rem;font-weight:600}
.feat p{margin-top:9px;font-size:.95rem}
@media(max-width:900px){.feat-grid{grid-template-columns:1fr 1fr}}
@media(max-width:560px){.feat-grid{grid-template-columns:1fr}}

/* ============ PROCESS ============ */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;position:relative;z-index:1}
.step{position:relative;padding-top:16px;border-top:3px solid var(--line)}
.step.on{border-top-color:var(--gold)}
.step .sn{font-family:var(--disp);font-weight:700;font-size:2.6rem;color:var(--gold);line-height:1}
.step h3{margin-top:8px;font-size:1.16rem;font-weight:600}
.step p{margin-top:9px;font-size:.94rem}
@media(max-width:820px){.steps{grid-template-columns:1fr 1fr}}
@media(max-width:480px){.steps{grid-template-columns:1fr}}

/* ============ STATS band ============ */
.statsband{background:var(--mist);position:relative;z-index:1}
.statsband .wrap{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}
.sb{background:#fff;padding:38px 28px;text-align:center}
.sb b{font-family:var(--disp);font-weight:700;font-size:3rem;color:var(--navy);line-height:1;display:block}
.sb b span{color:var(--gold)}
.sb small{display:block;margin-top:8px;color:var(--muted);font-size:.76rem;letter-spacing:.14em;text-transform:uppercase;font-weight:700}
@media(max-width:720px){.statsband .wrap{grid-template-columns:1fr 1fr}}

/* ============ GOVERNMENT ============ */
.gov{background:var(--mist);overflow:hidden}
.gov-grid{display:grid;grid-template-columns:.95fr 1.05fr;gap:70px;align-items:center;position:relative;z-index:1}
.gov-fig{position:relative}
.gov-fig .main{width:100%;aspect-ratio:4/3;object-fit:cover}
.gov-fig .inset{position:absolute;right:-24px;bottom:-30px;width:44%;aspect-ratio:1/1;object-fit:cover;border:6px solid var(--mist);box-shadow:0 20px 40px rgba(13,37,69,.2)}
.gov-fig .flag{position:absolute;top:0;left:0;background:var(--blue);color:#fff;font-family:var(--f);font-size:.68rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;padding:10px 16px;z-index:2}
.gov-copy h2{font-size:clamp(1.9rem,3.6vw,2.9rem);margin:22px 0 20px;line-height:1.04}
.gov-copy h2 em{font-style:normal;color:var(--blue)}
.gov-copy .lead{font-size:1.05rem;color:var(--ink);margin-bottom:26px;font-family:var(--f)}
.gov-check{list-style:none;margin:0 0 30px;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:14px 24px}
.gov-check li{display:flex;gap:12px;font-size:.96rem;color:var(--ink);font-weight:500;font-family:var(--f)}
.gov-check .ic{width:22px;height:22px;color:#fff;background:var(--blue);padding:3px;flex:none;stroke-width:3}
.gov-actions{display:flex;gap:14px;flex-wrap:wrap}
.gov-proof{margin-top:30px;padding-top:24px;border-top:1px solid var(--line);display:flex;align-items:center;gap:18px;flex-wrap:wrap}
.gov-proof .pl{font-family:var(--f);font-size:.7rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}
.gov-proof .chip{font-family:var(--disp);font-weight:500;text-transform:uppercase;font-size:.95rem;color:var(--navy);background:#fff;border:1px solid var(--line);padding:8px 15px}
.gov-proof .chip b{color:var(--blue)}
@media(max-width:900px){.gov-grid{grid-template-columns:1fr;gap:56px}.gov-check{grid-template-columns:1fr}.gov-fig .inset{width:40%}}

/* compliance strip */
.compliance{background:var(--navy-3);color:#fff}
.compliance .wrap{display:flex;flex-wrap:wrap;justify-content:space-between;gap:24px 30px;padding:34px var(--gut)}
.compliance .ci{display:flex;align-items:center;gap:14px}
.compliance .ci .ic{width:26px;height:26px;color:var(--gold);stroke-width:2}
.compliance .ci b{font-family:var(--disp);font-weight:500;text-transform:uppercase;font-size:1.05rem;color:#fff;letter-spacing:.02em}
.compliance .ci small{display:block;color:#9fb0c6;font-size:.74rem;font-family:var(--f);letter-spacing:.04em}

/* ============ PROJECTS ============ */
.projects{background:var(--white);overflow:hidden}
.pj-head{display:flex;align-items:flex-end;justify-content:space-between;gap:30px;margin-bottom:52px;position:relative;z-index:1}
.pj-head h2{font-size:clamp(2rem,4vw,3.2rem);margin-top:20px}
.pj-grid{display:grid;grid-template-columns:1fr 1fr;gap:26px;position:relative;z-index:1}
.pj{background:#fff;overflow:hidden;position:relative;display:flex;flex-direction:column;border:1px solid var(--line);transition:.3s}
.pj:hover{transform:translateY(-8px);box-shadow:0 30px 60px rgba(13,37,69,.16);border-color:transparent}
.pj-img{position:relative;aspect-ratio:16/9;overflow:hidden}
.pj-img img{width:100%;height:100%;object-fit:cover;transition:.55s}
.pj:hover .pj-img img{transform:scale(1.07)}
.pj-img .idx{position:absolute;top:0;left:0;background:var(--navy);color:#fff;font-family:var(--disp);font-size:1.05rem;font-weight:700;letter-spacing:.12em;padding:8px 18px}
.pj-img .tag{position:absolute;bottom:14px;right:14px;background:var(--gold);color:var(--navy);font-family:var(--f);font-size:.66rem;letter-spacing:.14em;text-transform:uppercase;font-weight:700;padding:7px 12px}
.pj-body{padding:30px 32px 32px}
.pj-body h3{font-size:1.6rem;font-weight:600}
.pj-scope{margin-top:15px}
.pj-scope .sl{font-family:var(--f);font-size:.68rem;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);font-weight:700}
.pj-scope ul{list-style:none;margin:12px 0 0;padding:0;display:grid;gap:10px}
.pj-scope li{display:flex;gap:13px;font-size:.98rem;color:var(--body)}
.pj-scope li::before{content:"";width:8px;height:8px;background:var(--gold);flex:none;margin-top:8px;transform:rotate(45deg)}
.pj-body .plink{display:inline-flex;align-items:center;gap:11px;margin-top:22px;font-family:var(--f);font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;font-weight:700;color:var(--navy);border-bottom:2px solid var(--gold);padding-bottom:6px}
.pj-body .plink .ic{width:15px;height:15px;stroke-width:2.6;transition:.2s}
.pj-body .plink:hover .ic{transform:translateX(6px)}
@media(max-width:820px){.pj-grid{grid-template-columns:1fr}.pj-head{flex-direction:column;align-items:flex-start}}

/* ============ GALLERY ============ */
.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;position:relative;z-index:1}
.gallery .g{aspect-ratio:4/3;overflow:hidden}
.gallery .g.wide{grid-column:span 2;aspect-ratio:auto}
.gallery img{width:100%;height:100%;object-fit:cover;transition:.5s}
.gallery .g:hover img{transform:scale(1.06)}
@media(max-width:760px){.gallery{grid-template-columns:1fr 1fr}.gallery .g.wide{grid-column:span 2}}

/* ============ TESTIMONIALS ============ */
.testi{background:var(--navy);color:#fff;position:relative;overflow:hidden}
.testi .wm{color:#fff}
.testi .olabel{color:#fff}
.testi-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.12);margin-top:52px;position:relative;z-index:2}
.tcard{background:var(--navy);padding:40px 32px;display:flex;flex-direction:column;transition:.3s;position:relative}
.tcard::before{content:"\201C";position:absolute;top:14px;right:24px;font-family:Georgia,serif;font-size:5rem;color:var(--gold);opacity:.5;line-height:1}
.tcard:hover{background:var(--navy-2)}
.tcard .stars{display:flex;gap:4px;color:var(--gold);margin-bottom:20px}
.tcard .stars .ic{width:17px;height:17px;fill:currentColor;stroke:none}
.tcard p{color:#d3ddec;font-size:.98rem;line-height:1.78;flex:1;font-family:var(--f)}
.tcard .by{margin-top:26px;padding-top:22px;border-top:1px solid rgba(255,255,255,.14)}
.tcard .by b{font-family:var(--disp);color:#fff;font-size:1.22rem;font-weight:600;display:block;letter-spacing:.01em}
.tcard .by small{color:#9fb0c6;font-size:.82rem;font-family:var(--f)}
@media(max-width:900px){.testi-grid{grid-template-columns:1fr}}

/* ============ CONTACT ============ */
.contact{background:var(--mist);overflow:hidden}
.ct-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:60px;align-items:start;position:relative;z-index:1}
.ct-copy h2{font-size:clamp(2rem,4vw,3rem);margin:22px 0 20px;line-height:1.02}
.ct-copy h2 em{font-style:normal;color:var(--blue)}
.ct-copy p{font-size:1.04rem;color:var(--ink);margin-bottom:18px;max-width:48ch;font-family:var(--f)}
.ct-lines{margin-top:30px;display:grid;gap:1px;background:var(--line);border:1px solid var(--line)}
.ct-lines a,.ct-lines .li{background:#fff;display:flex;align-items:flex-start;gap:16px;padding:20px 22px;font-size:1rem;color:var(--navy);font-family:var(--f)}
.ct-lines a{font-family:var(--disp);font-weight:500;align-items:center;transition:.2s}
.ct-lines a:hover{background:var(--blue-050);padding-left:30px}
.ct-lines .ic{width:20px;height:20px;color:var(--blue);stroke-width:1.9;flex:none;margin-top:2px}
.ct-lines .li b{font-family:var(--disp);color:var(--navy);text-transform:uppercase;letter-spacing:.02em;display:block;font-weight:600;font-size:1.02rem}
.ct-lines .li small{color:var(--body);font-size:.92rem}
/* form */
.cform{background:#fff;border:1px solid var(--line);padding:36px}
.cform h3{font-size:1.5rem;font-weight:600}
.cform .sub{font-family:var(--f);color:var(--muted);font-size:.9rem;margin-top:4px}
.frow{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:20px}
.field{display:flex;flex-direction:column;gap:7px;margin-top:14px}
.field.full{grid-column:1/-1}
.field label{font-family:var(--f);font-size:.74rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--ink)}
.field input,.field select,.field textarea{border:1.5px solid var(--line);background:#fff;padding:14px 15px;font:inherit;font-size:.96rem;color:var(--ink);outline:none;transition:.18s;border-radius:0}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--blue)}
.field textarea{resize:vertical;min-height:120px}
.cform .btn{width:100%;margin-top:20px}
.cform .fine{font-family:var(--f);font-size:.76rem;color:var(--muted);text-align:center;margin-top:14px}
@media(max-width:520px){.frow{grid-template-columns:1fr}}

/* offices */
.offices{display:grid;grid-template-columns:1fr 1fr;gap:26px;position:relative;z-index:1}
.office{background:#fff;border:1px solid var(--line);overflow:hidden}
.office .omap{aspect-ratio:16/9;position:relative}
.office .obody{padding:24px 26px 26px}
.office h3{font-size:1.3rem;font-weight:600}
.office .oaddr{margin-top:10px;font-family:var(--f);color:var(--body);font-size:.98rem}
.office .orow{display:flex;gap:10px;align-items:center;margin-top:12px;font-family:var(--f);font-weight:600;color:var(--navy)}
.office .orow .ic{width:17px;height:17px;color:var(--blue)}
@media(max-width:720px){.offices{grid-template-columns:1fr}}

/* email capture */
.emailcap{background:var(--blue);color:#fff;position:relative;overflow:hidden}
.emailcap::before{content:"";position:absolute;top:0;right:0;width:40%;height:100%;background:repeating-linear-gradient(45deg,rgba(255,255,255,.07) 0 14px,transparent 14px 28px)}
.emailcap .wrap{display:grid;grid-template-columns:1fr auto;gap:40px;align-items:center;padding:56px var(--gut);position:relative;z-index:1}
.emailcap h2{color:#fff;font-size:clamp(1.6rem,3vw,2.3rem)}
.emailcap p{color:#eaf6f9;font-family:var(--f);margin-top:10px}
.ec-actions{display:flex;gap:14px;flex-wrap:wrap;justify-content:flex-end}
.emailcap .btn-dark{background:var(--navy);color:#fff;border-color:var(--navy)}
.emailcap .btn-dark::before{background:#081627}
.emailcap .btn-wt{background:#fff;color:var(--blue-d);border-color:#fff}
.emailcap .btn-wt::before{background:var(--gold)}
.emailcap .btn-wt:hover{color:var(--navy)}
@media(max-width:820px){.emailcap .wrap{grid-template-columns:1fr;gap:22px}.ec-actions{justify-content:flex-start}}

/* ============ FOOTER ============ */
footer.site{background:var(--navy-3);color:rgba(255,255,255,.6);padding:78px 0 30px}
.foot-top{display:grid;grid-template-columns:1.7fr 1fr 1fr 1.2fr;gap:44px;padding-bottom:44px;border-bottom:1px solid var(--line-ink)}
.foot-brand img{height:82px;width:auto;margin-bottom:22px}
.foot-brand p{font-size:.95rem;max-width:40ch;color:rgba(255,255,255,.55);font-family:var(--f)}
.foot-brand .fcontact{margin-top:22px;display:grid;gap:12px}
.foot-brand .fcontact a{display:inline-flex;align-items:center;gap:12px;font-size:1.05rem;color:#eaeef4;font-family:var(--disp);font-weight:500}
.foot-brand .fcontact a:hover{color:var(--gold)}
.foot-brand .fcontact .ic{width:18px;height:18px;color:var(--gold);stroke-width:1.9}
footer.site h4{color:#fff;font-family:var(--f);font-size:.74rem;letter-spacing:.22em;text-transform:uppercase;font-weight:700;margin:0 0 22px}
footer.site .fcol ul{list-style:none;margin:0;padding:0;display:grid;gap:13px}
footer.site .fcol a{font-size:.95rem;letter-spacing:.02em;font-family:var(--f);color:rgba(255,255,255,.6)}
footer.site .fcol a:hover{color:var(--gold);padding-left:5px;transition:.2s}
.foffice{font-family:var(--f);font-size:.92rem;color:rgba(255,255,255,.6);line-height:1.6}
.foffice b{color:#fff;font-family:var(--disp);font-weight:500;text-transform:uppercase;letter-spacing:.02em;display:block;margin-bottom:3px}
.foffice+.foffice{margin-top:16px}
.foot-bottom{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;padding-top:26px;font-size:.82rem;color:rgba(255,255,255,.42);letter-spacing:.04em;font-family:var(--f)}
.foot-bottom .legal{display:flex;gap:22px;flex-wrap:wrap}
.foot-credit{text-align:center;margin-top:18px;padding-top:16px;border-top:1px solid var(--line-ink);font-family:var(--f);font-size:.8rem;letter-spacing:.04em;color:rgba(255,255,255,.4)}
@media(max-width:960px){.foot-top{grid-template-columns:1fr 1fr;gap:34px}.foot-brand{grid-column:1/-1}}
@media(max-width:560px){.foot-top{grid-template-columns:1fr}.foot-bottom{flex-direction:column;text-align:center;justify-content:center}.foot-bottom .legal{justify-content:center}}

/* sticky mobile call bar */
.callbar{display:none}
@media(max-width:720px){
  .callbar{display:grid;grid-template-columns:1fr 1fr;position:fixed;left:0;right:0;bottom:0;z-index:90}
  .callbar a{padding:16px;text-align:center;font-family:var(--f);font-weight:700;font-size:.78rem;letter-spacing:.14em;text-transform:uppercase;display:flex;align-items:center;justify-content:center;gap:9px}
  .callbar .c1{background:var(--gold);color:var(--navy)}.callbar .c2{background:var(--navy);color:#fff}
  .callbar .ic{width:16px;height:16px;stroke-width:2.4}
  body{padding-bottom:54px}
}
.totop{position:fixed;right:22px;bottom:24px;width:46px;height:46px;background:var(--navy);color:#fff;display:grid;place-items:center;z-index:50;border:2px solid var(--gold);transition:.2s}
.totop:hover{background:var(--gold);color:var(--navy)}
.totop .ic{width:20px;height:20px;stroke-width:2.6}
@media(max-width:720px){.totop{bottom:70px}}
.demonote{background:var(--navy-3);color:#aeb9cb;font-size:.78rem;text-align:center;padding:9px 16px;letter-spacing:.04em;font-family:var(--f)}
.demonote b{color:#fff}
